<?php
 namespace App; use Carbon\Carbon; use Illuminate\Notifications\Notifiable; use Illuminate\Foundation\Auth\User as Authenticatable; use Tymon\JWTAuth\Contracts\JWTSubject; class User extends Authenticatable implements JWTSubject { use Notifiable, \App\Concerns\SerializesLegacyDates; protected $guarded = []; protected $hidden = [ 'password', 'remember_token' ]; protected $appends = ['m_balance', 'role']; protected $casts = [ 'theme_config' => 'array' ]; const ID_CUSTOMER = -1; const INVENTORY_RANGE = 0; const INVENTORY_REAL = 1; const INVENTORY_AUTO = 2; const FEE_TYPE_MERCHANT = 0; const FEE_TYPE_CUSTOMER = 1; const FEE_TYPE_AUTO = 2; const STATUS_OK = 0; const STATUS_FROZEN = 1; public function getJWTIdentifier() { return $this->getKey(); } public function getJWTCustomClaims() { return []; } public function sendPasswordResetNotification($token) { throw new \Exception('unimplemented in free version'); } function getMBalanceAttribute() { return $this->m_all - $this->m_paid - $this->m_frozen; } function getRoleAttribute(){ return 'admin'; } function getMBalanceWithoutTodayAttribute() { $income_today = (int)\App\Order::where('user_id', $this->user_id) ->where('status', \App\Order::STATUS_SUCCESS)->whereDate('paid_at', Carbon::today())->sum('income'); return $this->m_all - $this->m_paid - $this->m_frozen - $income_today; } function getShopThemeAttribute() { if ($this->theme_config && isset($this->theme_config['theme'])) { $ret = \App\ShopTheme::whereName($this->theme_config['theme'])->first(); if ($ret) return $ret; } return \App\ShopTheme::defaultTheme(); } function getLastLoginAtAttribute() { $last_login_log = $this->logs()->where('action', \App\Log::ACTION_LOGIN)->orderBy('id', 'DESC')->first(); return $last_login_log ? ($last_login_log->address ?? $last_login_log->ip) : null; } function categories() { return $this->hasMany(Category::class); } function products() { return $this->hasMany(Product::class); } function cards() { return $this->hasMany(Card::class); } function orders() { return $this->hasMany(Order::class); } function coupons() { return $this->hasMany(Coupon::class); } function logs() { return $this->hasMany(Log::class); } function shop_theme() { return $this->belongsTo(ShopTheme::class); } } 